// Equal-date orders use string ordering, regardless of input order.
const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: '0', tenant: 'b', createdAt: '2026-01-02', total: 2 },
  { id: '2', tenant: 'a', createdAt: '2026-01-01', total: 3 },
  { id: 'z', tenant: 'a', createdAt: '2026-01-02', total: 4 },
  { id: '10', tenant: 'a', createdAt: '2026-01-01', total: 5 },
  { id: 'A', tenant: 'a', createdAt: '2026-01-01', total: 6 }
];
const original = structuredClone(rows);
rows.forEach(Object.freeze);
Object.freeze(rows);
const paginated = new OrderHandler(new OrderRepository(rows));
let cursor;
const ids = [];
do {
  const page = paginated.list({ tenant: 'a', limit: 1, cursor });
  ids.push(...page.items.map(row => row.id));
  cursor = page.nextCursor;
} while (cursor !== null);
assert.deepEqual(ids, ['10', '2', 'A', 'b', 'z']);
assert.deepEqual(rows, original);
assert.equal(paginated.list({ tenant: 'a', limit: 4 }).nextCursor, '2026-01-01|b');
assert.equal(paginated.list({ tenant: 'a', limit: 5 }).nextCursor, null);
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });
// The boundary need not exist, and may belong to another tenant.
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor: '2026-01-01|B' }).items.map(row => row.id), ['b', 'z']);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-02|0' }).items.map(row => row.id), ['z']);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2027|x' }), { items: [], nextCursor: null });
const remaining = new OrderHandler(new OrderRepository(rows.filter(row => row.id !== '2')));
assert.deepEqual(remaining.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|2' }).items.map(row => row.id), ['A']);
for (const cursor of ['', 'x', '|x', 'x|', 'x|y|z', null, 42]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), { message: 'invalid request' });
}
for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1', undefined]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit }), { message: 'invalid request' });
}
assert.throws(() => paginated.list({ tenant: '', limit: 1 }), { message: 'invalid request' });

